<script setup>
import { computed, defineComponent, h, ref } from 'vue'
import { Activity, ArrowRight, Bell, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, ClipboardList, Clock3, Command, Database, FileSearch, Layers, LayoutDashboard, Menu, MessageSquare, MoreHorizontal, Palette, Plus, Radio, RotateCcw, Search, Send, Settings, ShieldCheck, Sparkles, TrendingUp, Upload, Users, X, Zap, UserRound, CalendarDays } from 'lucide-vue-next'

const theme=ref('light'), page=ref('dashboard'), mobileOpen=ref(false), modal=ref(''), toastText=ref(''), accountSearch=ref(''), groupSearch=ref(''), taskFilter=ref('全部'), settingTab=ref('外观主题'), draftName=ref(''), draftNote=ref('')
const nav=[{id:'dashboard',label:'工作台',icon:LayoutDashboard},{id:'accounts',label:'账号管理',icon:Users,badge:'12'},{id:'groups',label:'群组库',icon:Layers},{id:'broadcast',label:'群发任务',icon:MessageSquare},{id:'join',label:'加群任务',icon:UserRound},{id:'scrape',label:'采集任务',icon:FileSearch},{id:'tasks',label:'任务中心',icon:ClipboardList}]
