const accounts=ref([{id:1,name:'运营主账号',phone:'+1 202 *** 0188',initial:'O',color:'#e5eaff',status:'在线',device:'iOS 设备',note:'主运营'},{id:2,name:'内容账号 02',phone:'+1 202 *** 0236',initial:'C',color:'#f0e8ff',status:'在线',device:'iOS 设备',note:'内容分发'},{id:3,name:'备用账号 A',phone:'+1 202 *** 0471',initial:'A',color:'#e2f5ed',status:'待检测',device:'iOS 设备',note:'备用'},{id:4,name:'社群账号 04',phone:'+1 202 *** 0629',initial:'S',color:'#fff0df',status:'在线',device:'iOS 设备',note:'社群维护'},{id:5,name:'品牌账号 05',phone:'+1 202 *** 0912',initial:'B',color:'#fce8ee',status:'在线',device:'iOS 设备',note:'品牌'},{id:6,name:'备用账号 B',phone:'+1 202 *** 1044',initial:'B',color:'#e6f0f8',status:'待检测',device:'iOS 设备',note:'备用'}])
