const filteredGroups=computed(()=>groups.value.filter(g=>(g.name+g.link).toLowerCase().includes(groupSearch.value.toLowerCase())))
const tasks=ref([{id:'T-1024',name:'品牌内容周更',type:'群发任务',status:'已完成',progress:100,account:'运营主账号',time:'今天 10:24'},{id:'T-1023',name:'社群资源整理',type:'采集任务',status:'运行中',progress:68,account:'内容账号 02',time:'今天 09:46'},{id:'T-1022',name:'新群组拓展',type:'加群任务',status:'已暂停',progress:32,account:'备用账号 A',time:'昨天 18:12'},{id:'T-1021',name:'活动通知草稿',type:'群发任务',status:'失败',progress:0,account:'社群账号 04',time:'昨天 16:08'},{id:'T-1020',name:'行业群组收集',type:'采集任务',status:'已完成',progress:100,account:'品牌账号 05',time:'昨天 14:30'}])
const filteredTasks=computed(()=>tasks.value.filter(t=>(taskFilter.value==='全部'||t.status===taskFilter.value)))
const pageDescriptions={broadcast:'查看群发任务的设计与状态展示。',join:'查看加群任务的设计与状态展示。',scrape:'查看采集任务的设计与状态展示。',tasks:'统一查看工作空间中的任务记录。'}
const settingTabs=['外观主题','工作空间','通知偏好','安全设置']
const themes=[{id:'light',label:'标准浅色'},{id:'eye',label:'护眼模式'},{id:'dark',label:'深色模式'}]
const helpCards=[{title:'账号管理',desc:'账号卡片、状态标签与常用操作布局。',icon:Users},{title:'任务工作流',desc:'任务列表、进度、筛选和详情交互。',icon:ClipboardList},{title:'主题与适配',desc:'标准、护眼、深色主题及移动端适配。',icon:Palette}]
function go(id){page.value=id;mobileOpen.value=false;taskFilter.value='全部'}
function openCreate(){draftName.value='';draftNote.value='';modal.value='task'}
function confirmModal(){if(modal.value==='account'){accounts.value.unshift({id:Date.now(),name:draftName.value||'新建演示账号',phone:'未绑定手机号',initial:'N',color:'#e5eaff',status:'待检测',device:'iOS 设备',note:draftNote.value||'演示账号'})}else{tasks.value.unshift({id:'T-'+(1025+tasks.value.length),name:draftName.value||'新建演示任务',type:currentLabel.value,status:'已暂停',progress:0,account:'演示账号',time:'刚刚'})}modal.value='';toast('已添加本地演示数据')}
function detailTask(t){toast('任务详情：'+t.name+'（演示）')}
let toastTimer
function toast(msg){toastText.value=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastText.value='',2400)}
const PageHeading=defineComponent({props:{title:String,desc:String},setup(p,{slots}){return()=>h('div',{class:'page-heading'},[h('div',[h('div',{class:'eyebrow'},'WORKSPACE'),h('h1',p.title),h('p',p.desc)]),h('div',{class:'heading-actions'},slots.default?.())])}})
const TaskTable=defineComponent({props:{rows:Array},emits:['detail'],setup(p,{emit}){return()=>h('div',{class:'table-wrap'},[h('table',[h('thead',[h('tr',['任务名称','类型','状态','进度','执行账号','创建时间',''].map(x=>h('th',x)))]),h('tbody',p.rows?.length?p.rows.map(t=>h('tr',[h('td',h('button',{class:'task-name',onClick:()=>emit('detail',t)},t.name)),h('td',h('span',{class:'soft-tag'},t.type)),h('td',h('span',{class:['status-pill',t.status==='已完成'?'success':t.status==='运行中'?'info':t.status==='失败'?'danger':'warning']},[h('i'),t.status])),h('td',h('div',{class:'progress-cell'},[h('div',{class:'progress-track'},[h('i',{style:{width:t.progress+'%'}})]),h('small',t.progress+'%')])),h('td',t.account),h('td',{class:'muted'},t.time),h('td',h('button',{class:'icon-btn',onClick:()=>emit('detail',t)},'···'))])):[h('tr',[h('td',{colspan:7,class:'empty-cell'},'暂无符合条件的任务')])])])])}}})
</script>
